CREATE TABLE IF NOT EXISTS public.tachograph_cards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  country text NOT NULL,
  country_flag text NOT NULL DEFAULT '',
  generation text NOT NULL DEFAULT '',
  application text NOT NULL DEFAULT '',
  current_manufacturer text NOT NULL DEFAULT '',
  current_manufacturer_normalized text NOT NULL DEFAULT '',
  chip_platform_vendor text NOT NULL DEFAULT '',
  security_certificate text NOT NULL DEFAULT '',
  chip_certificate text NOT NULL DEFAULT '',
  type_approval_number text NOT NULL DEFAULT '',
  certified_security_platform text NOT NULL DEFAULT '',
  certificate_holder text NOT NULL DEFAULT '',
  date_status text NOT NULL DEFAULT '',
  issued_by_authority text NOT NULL DEFAULT '',
  jrc_interoperability_status text NOT NULL DEFAULT '',
  functional_certificate_lab text NOT NULL DEFAULT '',
  security_certificate_lab text NOT NULL DEFAULT '',
  tachograph_application_os text NOT NULL DEFAULT '',
  distinction_from_manufacturer text NOT NULL DEFAULT '',
  jrc_certificate_source text NOT NULL DEFAULT '',
  primary_source text NOT NULL DEFAULT '',
  latest_tender text NOT NULL DEFAULT '',
  winner_contractor text NOT NULL DEFAULT '',
  procurement_status text NOT NULL DEFAULT '',
  procurement_scope text NOT NULL DEFAULT '',
  tender_source text NOT NULL DEFAULT '',
  verification_note text NOT NULL DEFAULT '',
  data_reference_date date NOT NULL DEFAULT '2026-07-15',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.jrc_update_proposals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fingerprint text NOT NULL UNIQUE,
  kind text NOT NULL DEFAULT 'changed',
  card_id uuid REFERENCES public.tachograph_cards(id) ON DELETE CASCADE,
  country text NOT NULL DEFAULT '',
  generation text NOT NULL DEFAULT '',
  jrc_manufacturer text NOT NULL DEFAULT '',
  jrc_card_name text NOT NULL DEFAULT '',
  jrc_certificate text NOT NULL DEFAULT '',
  jrc_date text NOT NULL DEFAULT '',
  jrc_eov text NOT NULL DEFAULT '',
  jrc_type_approval text NOT NULL DEFAULT '',
  source_url text NOT NULL DEFAULT '',
  changes jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'pending',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  source_type text NOT NULL DEFAULT 'card_status',
  source_label text NOT NULL DEFAULT 'Card status',
  title text NOT NULL DEFAULT '',
  payload jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS public.jrc_check_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_url text NOT NULL DEFAULT '',
  rows_parsed integer NOT NULL DEFAULT 0,
  proposals_created integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'ok',
  message text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  source_type text NOT NULL DEFAULT 'card_status'
);

CREATE TABLE IF NOT EXISTS public.jrc_source_snapshots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_type text NOT NULL,
  entry_key text NOT NULL,
  fingerprint text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_type, entry_key)
);

CREATE INDEX IF NOT EXISTS idx_tachograph_country ON public.tachograph_cards (country);
CREATE INDEX IF NOT EXISTS idx_tachograph_generation ON public.tachograph_cards (generation);
CREATE INDEX IF NOT EXISTS idx_tachograph_mfr_norm ON public.tachograph_cards (current_manufacturer_normalized);
CREATE INDEX IF NOT EXISTS jrc_update_proposals_source_type_idx ON public.jrc_update_proposals (source_type);

CREATE TABLE IF NOT EXISTS public.tachograph_card_overrides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  card_id uuid NOT NULL UNIQUE REFERENCES public.tachograph_cards(id) ON DELETE CASCADE,
  patch jsonb NOT NULL DEFAULT '{}'::jsonb,
  edited_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.cron_config (
  id boolean PRIMARY KEY DEFAULT true CHECK (id = true),
  token text NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
  endpoint text NOT NULL DEFAULT '',
  enabled boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

VALUES (true, '', false)
ON CONFLICT (id) DO NOTHING;


CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$ LANGUAGE plpgsql SET search_path = public;

CREATE TRIGGER update_jrc_update_proposals_updated_at
BEFORE UPDATE ON public.jrc_update_proposals
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

